from unittest.mock import patch

from src.rag.retriever import RAGRetriever
from src.rag.prompt import build_safety_prompt
from src.rag.models import RetrievedChunk


@patch.object(RAGRetriever, "retrieve")
def test_rag_pipeline(mock_retrieve):
    """Test the RAG pipeline using mocked retrieval results."""

    # Simulate a visual description generated by the vision model.
    visual_description = (
        "A person appears to be lying on the ground "
        "on an icy outdoor surface."
    )

    # Predefine the guideline chunks returned by the retriever.
    # These replace the real PostgreSQL search results.
    sample_chunks = [
        RetrievedChunk(
            document_name="fall_response.md",
            section="1. Incident Verification",
            content="Verify whether a person has fallen.",
            similarity=0.82,
        ),
        RetrievedChunk(
            document_name="fall_response.md",
            section="2. Immediate Response",
            content="Check whether the person is conscious.",
            similarity=0.91,
        ),
    ]

    # Configure the mock retriever to return the predefined chunks.
    mock_retrieve.return_value = sample_chunks

    # Create the retriever.
    retriever = RAGRetriever()

    # Retrieve safety guidelines for the incident.
    # The mocked retrieve() method avoids Ollama and PostgreSQL.
    chunks = retriever.retrieve(
        visual_description,
        top_k=3,
    )

    # Build the actual prompt using the retrieved guidelines.
    prompt = build_safety_prompt(
        visual_description,
        chunks,
    )

    print()
    print(prompt)
    
    # Verify that the retriever received the correct input.
    mock_retrieve.assert_called_once_with(
        visual_description,
        top_k=3,
    )

    # Verify that the expected chunks were returned.
    assert len(chunks) == 2

    # Verify that the prompt contains the incident description.
    assert visual_description in prompt

    # Verify that the prompt contains the retrieved guidelines.
    assert "Verify whether a person has fallen." in prompt
    assert "Check whether the person is conscious." in prompt

    # Verify that the source information is included.
    assert "fall_response.md" in prompt
    assert "1. Incident Verification" in prompt
    assert "2. Immediate Response" in prompt